const html = $input.first().json.data ?? "";
const clean = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;|&#160;/g, " ")
  .replace(/\s+/g, " ")
  .trim();
const offers = [];
const seen = new Set();
const re = /([A-Z][A-Za-z0-9'&.\- ]{3,60}?)\s*(?:[-\u2013\u2014:|]\s*)?(?:get\s+|up\s+to\s+)?(\d{1,2})\s*%\s*(off|discount|cashback)?/gi;
let m;
while ((m = re.exec(clean)) !== null && offers.length < 20) {
  const merchant = m[1].trim().split(/\s{2,}/)[0].slice(0, 32);
  const key = merchant.toLowerCase();
  if (seen.has(key) || merchant.length < 3) continue;
  seen.add(key);
  offers.push({ merchant, value: Number(m[2]), cashback: /cashback/i.test(m[3] || "") });
}
return [{ json: { offers, pageChars: clean.length } }];

const TARGET = "https://www.alrajhibank.com.sa/en/personal/cards/credit-cards/card-offers";
const { offers, pageChars } = $input.first().json;
const now = new Date();
const norm = offers.map((o, i) => ({
  id: "alrajhi-" + now.getTime().toString(36) + "-" + i,
  merchant: o.merchant,
  headline: o.merchant + " \u2014 " + o.value + "% " + (o.cashback ? "cashback" : "off") + " for Al Rajhi card holders",
  discountLabel: "\u2212" + o.value + "%",
  value: o.value,
  kind: o.cashback ? "cashback" : "percent",
  category: "online",
  bank: "Al Rajhi Bank",
  card: /infinite/i.test(o.merchant) ? "Visa Infinite" : /signature/i.test(o.merchant) ? "Signature Visa" : "All credit tiers",
  image: "",
  cards: ["Al Rajhi credit cards"],
  link: TARGET,
  expiresAt: null,
  terms: ["Parsed by the onlydeals-alrajhi n8n workflow \u2014 open the link for full terms."]
}));
const payload = {
  version: "offer.v1",
  generatedAt: now.toISOString(),
  generator: "n8n:onlydeals-alrajhi",
  sources: [{
    id: "alrajhi",
    name: "Al Rajhi Bank",
    status: norm.length ? "live" : "error",
    count: norm.length,
    note: norm.length + " offers \u00b7 html regex \u00b7 " + pageChars + " chars parsed",
    at: now.getTime()
  }],
  offers: norm
};
return [{ json: { payload, count: norm.length } }];

const p = $('Build offer.v1 payload').first().json.payload;
const s = (p.sources && p.sources[0]) || {};
return [{ json: { timestamp: p.generatedAt, source: s.id || '', offers: s.count || 0, status: s.status || '', generator: p.generator } }];
